import { invoke } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";
import {
  incrementWireCounter,
  parseSshForwardError,
  parseUtcTimestamp,
  parseWireCounter,
  wireCounterToBigInt,
  type DesktopClientContext,
  type KeyInventory,
  type KnownScopesInput,
  type OpenClientResult,
  type ScopeActivation,
  type SshForwardError,
  type SshForwardEventHint,
  type SshForwardHost,
  type SshForwardHostEvent,
  type SshForwardProfile,
  type SshForwardSnapshot,
  type WireCounter,
} from "@dam-hopper/ui/lib/ssh-forward-host";

export const NATIVE_SSH_FORWARD_COMMANDS = {
  openClient: "ssh_forward_open_client", activateScope: "ssh_forward_activate_scope", snapshot: "ssh_forward_snapshot",
  createProfile: "ssh_forward_create_profile", updateProfile: "ssh_forward_update_profile", deleteProfile: "ssh_forward_delete_profile",
  start: "ssh_forward_start", stop: "ssh_forward_stop", restart: "ssh_forward_restart", listKeys: "ssh_forward_list_keys",
  approveHost: "ssh_forward_approve_host", purgeScope: "ssh_forward_purge_scope",
} as const satisfies Record<Exclude<keyof SshForwardHost, "subscribe" | "dispose">, string>;

const IPC_UNAVAILABLE: SshForwardError = { code: "IPC_UNAVAILABLE", message: "Native SSH forwarding is temporarily unavailable.", retryable: true };
const UUID_V4 = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const FINGERPRINT = /^SHA256:[A-Za-z0-9+/]{43}$/;
const STATES = new Set(["stopped", "starting", "running", "reconnecting", "stopping", "failed"]);
const DISPOSITIONS = new Set(["notRequested", "queued", "started", "skippedActiveLimit"]);
const REASONS = new Set(["profilesChanged", "runtimeChanged", "trustChanged"]);
const ALGORITHMS = new Set(["ssh-ed25519", "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521"]);

function record(value: unknown): Record<string, unknown> | null { return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : null; }
function exactKeys(value: Record<string, unknown>, required: readonly string[], optional: readonly string[] = []): boolean {
  return required.every((key) => key in value) && Object.keys(value).every((key) => required.includes(key) || optional.includes(key));
}
function uuid(value: unknown): value is string { return typeof value === "string" && UUID_V4.test(value); }
function counter(value: unknown): value is WireCounter { return Boolean(parseWireCounter(value)); }
function port(value: unknown): value is number { return typeof value === "number" && Number.isInteger(value) && value >= 1 && value <= 65535; }
function boundedText(value: unknown, limit: number): value is string { return typeof value === "string" && value.length > 0 && [...value].length <= limit && !/[\u0000-\u001f\u007f]/.test(value); }
function safeAscii(value: unknown, limit: number): value is string { return typeof value === "string" && value.length > 0 && value.length <= limit && /^[A-Za-z0-9_-]+$/.test(value); }
function fingerprint(value: unknown): value is string { return typeof value === "string" && FINGERPRINT.test(value); }
function canonicalHost(value: unknown): value is string {
  if (typeof value !== "string" || value.length === 0 || value.length > 253 || value !== value.toLowerCase() || value.endsWith(".")) return false;
  if (/^\d+(?:\.\d+){3}$/.test(value)) return value.split(".").every((part) => /^(0|[1-9]\d{0,2})$/.test(part) && Number(part) <= 255);
  return value.split(".").every((label) => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(label));
}
function validContext(value: unknown): value is DesktopClientContext {
  const raw = record(value); return !!raw && exactKeys(raw, ["desktopInstanceId", "managerSessionId", "clientEpoch"]) && uuid(raw.desktopInstanceId) && uuid(raw.managerSessionId) && counter(raw.clientEpoch);
}
function sameContext(left: DesktopClientContext, right: DesktopClientContext): boolean { return left.desktopInstanceId === right.desktopInstanceId && left.managerSessionId === right.managerSessionId && left.clientEpoch === right.clientEpoch; }
function validProfile(value: unknown): boolean {
  const raw = record(value);
  if (!raw || !exactKeys(raw, ["id", "scopeId", "name", "sshHost", "sshPort", "sshUser", "auth", "localPort", "targetHost", "targetPort", "autoStart", "reconnect", "createdAt", "updatedAt"])) return false;
  const auth = record(raw.auth), reconnect = record(raw.reconnect);
  return uuid(raw.id) && uuid(raw.scopeId) && boundedText(raw.name, 64) && canonicalHost(raw.sshHost) && port(raw.sshPort) && boundedText(raw.sshUser, 64) && raw.targetHost === "127.0.0.1" && port(raw.localPort) && port(raw.targetPort) && typeof raw.autoStart === "boolean" && !!reconnect && exactKeys(reconnect, ["enabled", "maxAttempts"]) && typeof reconnect.enabled === "boolean" && typeof reconnect.maxAttempts === "number" && Number.isInteger(reconnect.maxAttempts) && reconnect.maxAttempts >= 0 && reconnect.maxAttempts <= 5 && !!auth && ((exactKeys(auth, ["mode"]) && auth.mode === "agent") || (exactKeys(auth, ["mode", "keyId"]) && auth.mode === "key" && safeAscii(auth.keyId, 128))) && validTimestamp(raw.createdAt) && validTimestamp(raw.updatedAt);
}
function validTimestamp(value: unknown): boolean { return Boolean(parseUtcTimestamp(value)); }
function validSnapshot(value: unknown, context: DesktopClientContext, token: WireCounter, scopeId: string, scopeGeneration: WireCounter): value is SshForwardSnapshot {
  const raw = record(value);
  if (!raw || !exactKeys(raw, ["context", "scopeId", "activationToken", "scopeGeneration", "profilesRevision", "trustRevision", "profiles", "runtimes", "hostKeyChallenges"]) || !validContext(raw.context) || !sameContext(raw.context, context) || raw.scopeId !== scopeId || raw.activationToken !== token || raw.scopeGeneration !== scopeGeneration || !counter(raw.profilesRevision) || !counter(raw.trustRevision) || !Array.isArray(raw.profiles) || !Array.isArray(raw.runtimes) || !Array.isArray(raw.hostKeyChallenges) || !raw.profiles.every(validProfile)) return false;
  return raw.runtimes.every((runtime) => { const item = record(runtime); return !!item && exactKeys(item, ["profileId", "generation", "state", "bindHost", "localPort", "retryAttempt", "activeChannels", "autoStartDisposition", "stateChangedAt"], ["startedAt", "errorCode"]) && uuid(item.profileId) && counter(item.generation) && typeof item.state === "string" && STATES.has(item.state) && item.bindHost === "127.0.0.1" && port(item.localPort) && typeof item.retryAttempt === "number" && Number.isInteger(item.retryAttempt) && item.retryAttempt >= 0 && item.retryAttempt <= 5 && typeof item.activeChannels === "number" && Number.isInteger(item.activeChannels) && item.activeChannels >= 0 && item.activeChannels <= 65535 && typeof item.autoStartDisposition === "string" && DISPOSITIONS.has(item.autoStartDisposition) && validTimestamp(item.stateChangedAt) && (item.startedAt === undefined || validTimestamp(item.startedAt)) && (item.errorCode === undefined || !!parseSshForwardError({ code: item.errorCode, message: "", retryable: false })); }) && raw.hostKeyChallenges.every((challenge) => { const item = record(challenge); return !!item && exactKeys(item, ["challengeId", "profileId", "scopeId", "generation", "sshHost", "sshPort", "algorithm", "fingerprint", "expiresAt"]) && uuid(item.challengeId) && uuid(item.profileId) && item.scopeId === scopeId && counter(item.generation) && canonicalHost(item.sshHost) && port(item.sshPort) && typeof item.algorithm === "string" && ALGORITHMS.has(item.algorithm) && fingerprint(item.fingerprint) && validTimestamp(item.expiresAt); });
